//! Cargo-driven `dbgeng.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", None),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ff37000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ff37000000u64)),
        o => panic!("dbgeng-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:wine", "import:psapi", "import:msvcrt", "import:ntdll", "import:version", "body", "engine:oldnames", "engine:delayimp_rust", "import:kernel32"],
        "x86_64" => &["engine:wine", "import:psapi", "import:msvcrt", "import:ntdll", "import:version", "body", "engine:oldnames", "engine:delayimp_rust", "import:kernel32"],
        "aarch64" => &["engine:wine", "import:psapi", "import:msvcrt", "import:ntdll", "import:version", "body", "engine:oldnames", "engine:delayimp_rust", "import:kernel32"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .c_from_compile_db("dbgeng_shims", &["dll/win32/dbgeng/dbgeng.c"])
        .spec2def("dll/win32/dbgeng/dbgeng.spec", "dbgeng.dll")
        .spec_stubs()
        .import_lib("dll/win32/psapi/psapi.spec", "psapi.dll", "psapi")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        .delay_import_lib("dll/win32/version/version.spec", "version.dll", "version")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
